CREATE TABLE webhook_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, page_id TEXT NOT NULL, lead_id TEXT NOT NULL, form_id TEXT NOT NULL, payload_hash TEXT NOT NULL, payload_json TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'received', received_at TEXT NOT NULL, processed_at TEXT, UNIQUE(workspace_id,page_id,lead_id));
CREATE INDEX webhooks_workspace_time ON webhook_events(workspace_id,received_at DESC);
CREATE TABLE sync_jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, page_id TEXT NOT NULL, form_id TEXT, lead_id TEXT, kind TEXT NOT NULL CHECK(kind IN('lead','history')), dedupe_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','complete','dead','cancelled')), attempts INTEGER NOT NULL DEFAULT 0, next_run_at TEXT NOT NULL, lease_until TEXT, lease_token TEXT, cursor TEXT, imported INTEGER NOT NULL DEFAULT 0, last_error TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(workspace_id,dedupe_key));
CREATE INDEX jobs_due ON sync_jobs(status,next_run_at);
CREATE INDEX jobs_workspace ON sync_jobs(workspace_id,created_at DESC);
CREATE TABLE lead_tombstones (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, page_id TEXT NOT NULL, lead_id TEXT NOT NULL, deleted_at TEXT NOT NULL, PRIMARY KEY(workspace_id,page_id,lead_id));
CREATE TABLE notification_reads (workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, seen_at TEXT NOT NULL, PRIMARY KEY(workspace_id,user_id), FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) ON DELETE CASCADE);
